// GENERATED by scripts/sync.js from core/state.js — edit that file, then run `npm run sync`.
// codequiz — shared mute state. Host-free: no host may add anything here.
// ponytail: one JSON file, no locking. Single user, single machine.

const fs = require('fs');
const path = require('path');
const os = require('os');

// One path for every host, so muting in one mutes them all.
const STATE_PATH =
  process.env.CODEQUIZ_STATE_PATH ||
  path.join(os.homedir(), '.codequiz-state.json');

const DEFAULT_STATE = { enabled: true, offUntil: 0, skip: 0, lastKind: 'product' };

function readState() {
  try {
    const raw = JSON.parse(fs.readFileSync(STATE_PATH, 'utf8'));
    return {
      enabled: raw.enabled !== false,
      offUntil: Number(raw.offUntil) || 0,
      skip: Math.max(0, Number(raw.skip) || 0),
      lastKind: raw.lastKind === 'code' ? 'code' : 'product',
    };
  } catch (e) {
    return { ...DEFAULT_STATE };
  }
}

function writeState(state) {
  try {
    fs.mkdirSync(path.dirname(STATE_PATH), { recursive: true });
    const tmp = STATE_PATH + '.tmp';
    fs.writeFileSync(tmp, JSON.stringify(state));
    fs.renameSync(tmp, STATE_PATH);
  } catch (e) {
    // Best-effort. A failed write must never block the prompt.
  }
}

const UNITS = { s: 1e3, m: 6e4, h: 36e5, d: 864e5 };

// "20" -> 20 prompts. "2h" / "90m" / "30s" / "1d" -> milliseconds.
function parseDuration(arg) {
  if (typeof arg !== 'string') return null;
  const s = arg.trim().toLowerCase();
  if (/^\d+$/.test(s)) {
    const n = parseInt(s, 10);
    return n > 0 ? { kind: 'prompts', value: n } : null;
  }
  const m = /^(\d+)\s*(s|m|h|d|sec|secs|min|mins|hr|hrs|day|days)$/.exec(s);
  if (!m) return null;
  const n = parseInt(m[1], 10);
  if (n <= 0) return null;
  return { kind: 'time', value: n * UNITS[m[2][0]], label: n + m[2][0] };
}

function humanRemaining(state, now = Date.now()) {
  if (!state.enabled) return 'off indefinitely';
  if (state.offUntil > now) {
    const mins = Math.ceil((state.offUntil - now) / 6e4);
    return mins >= 60
      ? `off for ~${Math.ceil(mins / 60)}h`
      : `off for ~${mins}m`;
  }
  if (state.skip > 0) return `off for ${state.skip} more prompt(s)`;
  return 'on';
}

module.exports = {
  DEFAULT_STATE,
  STATE_PATH,
  humanRemaining,
  parseDuration,
  readState,
  writeState,
};
